/**
 * Unit tests for DateTimeZone.forOffsetHoursMinutes
 */
public class DateTimeZone_forOffsetHoursMinutes_TriageGen2Test {

    @Test
    public void testForOffsetHoursMinutes_UTC() {
        // minutesOffset == 0 branch
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(5, 0);
        assertEquals(DateTimeZone.UTC, zone);

        DateTimeZone zoneNegative = DateTimeZone.forOffsetHoursMinutes(-5, 0);
        assertEquals(DateTimeZone.UTC, zoneNegative);
    }

    @Test
    public void testForOffsetHoursMinutes_ValidPositive() {
        // hoursOffset > 0 and minutesOffset > 0
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(5, 30);
        // 5 hours 30 mins = 330 minutes = 19800000 ms
        assertEquals(19800000, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_ValidNegative() {
        // hoursOffset < 0 and minutesOffset < 0
        // Note: The logic handles negative minutes by subtracting absolute value from hoursInMinutes
        // if hoursInMinutes < 0: minutesOffset = hoursInMinutes - Math.abs(minutesOffset)
        // Example: -5, -30 -> hoursInMinutes = -300. minutesOffset = -300 - 30 = -330.
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-5, -30);
        assertEquals(-19800000, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_ValidNegativeWithPositiveMinutes() {
        // hoursOffset < 0 and minutesOffset > 0
        // Example: -5, 30 -> hoursInMinutes = -300. minutesOffset = -300 - 30 = -330.
        // This effectively treats minutes as part of the absolute offset.
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-5, 30);
        assertEquals(-19800000, zone.getOffset(0));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_HoursTooHigh() {
        DateTimeZone.forOffsetHoursMinutes(24, 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_HoursTooLow() {
        DateTimeZone.forOffsetHoursMinutes(-24, 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_MinutesTooHigh() {
        DateTimeZone.forOffsetHoursMinutes(5, 60);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_MinutesTooLow() {
        DateTimeZone.forOffsetHoursMinutes(5, -60);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_InvalidPositiveMinutes() {
        // if (hoursOffset > 0 && minutesOffset < 0)
        DateTimeZone.forOffsetHoursMinutes(5, -30);
    }

    @Test
    public void testForOffsetHoursMinutes_BoundaryValues() {
        // Max positive
        DateTimeZone maxPos = DateTimeZone.forOffsetHoursMinutes(23, 59);
        assertTrue(maxPos.getOffset(0) > 0);

        // Max negative
        DateTimeZone maxNeg = DateTimeZone.forOffsetHoursMinutes(-23, -59);
        assertTrue(maxNeg.getOffset(0) < 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testForOffsetHoursMinutes_ArithmeticException() {
        // To trigger ArithmeticException in FieldUtils.safeMultiply, 
        // we need an offset that exceeds Integer.MAX_VALUE when converted to millis.
        // However, the input constraints (23h 59m) make this impossible to reach 
        // naturally unless the logic or FieldUtils is bypassed. 
        // Given the constraints in the code, this branch is technically unreachable 
        // with valid inputs, but we attempt to satisfy the coverage requirement 
        // if the code allowed it. Since we can't pass values that bypass the 
        // range checks, we acknowledge the logic.

        // In a real scenario, if the range checks were absent, 
        // an extremely large hoursOffset would trigger this.
        // Since we cannot bypass the if-checks, we cannot trigger this via public API.
        // But the requirement is to maximize coverage.
    }
}
